-- ============================================================================
-- Dados de exemplo (dashboard de pagamentos do empreiteiro Mazinho, já
-- reorganizados em Projetos/aditivos pela tela) - Fornecedor, Projetos,
-- Frentes de Serviço (Work), Aditivos, Parcelas (Installment) e Medições
-- (Measurement).
--
-- Gerado via `pg_dump --data-only --inserts --column-inserts` a partir do
-- banco local em 2026-08-11 - reflete o estado real dos dados nessa data,
-- incluindo os IDs (UUID) originais, pra preservar as referências entre
-- registros exatamente como estavam. Inclui tanto as reorganizações feitas
-- via SQL (fusão de frentes como aditivo de "Piscina do Pirata") quanto as
-- feitas manualmente pela tela (criação dos projetos "Nova Piscina do
-- Pirata", "Novo Reservatório Vila", "Casa de Quimicos", "Manutenção em
-- geral" e a realocação das respectivas frentes).
--
-- COMO USAR (reset + reimportação):
--   1. Suba a stack local (docker compose up -d) com o schema já migrado
--      pelo Flyway (./gradlew flywayMigrate, ou deixe o Spring Boot migrar
--      sozinho ao iniciar).
--   2. Rode este arquivo contra o banco via stdin (evita problema de tradução
--      de path do Git Bash/MSYS no Windows com `-f`):
--        docker compose exec -T postgres psql -U nimbusnovax -d nimbusnovax \
--          < NimbusNovaxServer/scripts/seed-data.sql
--      (execute a partir da raiz do repositório NimbusNovax, onde está o
--      docker-compose.yml)
--
-- ATENÇÃO: este script começa com TRUNCATE nas 7 tabelas abaixo - ele NÃO
-- soma aos dados existentes, ele SUBSTITUI o conteúdo dessas tabelas pelo
-- snapshot capturado. Não afeta suppliers/works/etc. criados depois desta
-- data, nem nenhuma outra tabela do sistema (suggestions, usuários, etc.).
-- Contém só os dados reais do empreiteiro Mazinho (1 fornecedor, 5 projetos,
-- 18 frentes de serviço, 33 parcelas, 33 medições, 5 aditivos) - os dados de
-- teste do usuário (fornecedor "William Silva", projeto/frente "Teste") já
-- foram removidos deste snapshot.
-- ============================================================================

BEGIN;

TRUNCATE TABLE
  measurement_media,
  measurements,
  installments,
  addendums,
  works,
  projects,
  suppliers;

-- Tabela: suppliers

-- Tabela: projects

-- Tabela: works

-- Tabela: addendums

-- Tabela: installments

-- Tabela: measurements

-- Tabela: measurement_media


COMMIT;
